import React from "react";
import { Excalidraw } from "@excalidraw/excalidraw";
import { render } from "./packages/excalidraw/tests/test-utils";
import { Keyboard, Pointer, UI } from "./packages/excalidraw/tests/helpers/ui";
import { KEYS } from "@excalidraw/common";

test("eraser-shortcut-during-line-drawing-keeps-line-tool", async () => {
  await render(
    React.createElement(Excalidraw, { handleKeyboardGlobally: true }),
  );
  const pointer = new Pointer("mouse");
  pointer.down(500, 200);
  pointer.move(425, 525);
  pointer.up();
  await Keyboard.keyPress(KEYS.E);
  UI.clickTool("line");
  const linePointer = new Pointer("mouse");
  await linePointer.clickAt(660, 590);
  await linePointer.clickAt(985, 340);
  await Keyboard.keyPress(KEYS.E);
  expect(window.h.state.activeTool.type).toBe("line");
});
